  toggle(name, force) { force ? this.values.add(name) : this.values.delete(name); }
  contains(name) { return this.values.has(name); }
}

function element(id) {
  return {
    id,
    textContent: "",
    hidden: id === "result",
    style: {},
    attributes: {},
    classList: new ClassList(),
    parentElement: null,
    setAttribute(name, value) { this.attributes[name] = value; },
  };
}

