  clearInterval() {},
  document: { getElementById: (id) => elements[id] },
  window: { addEventListener: (name, callback) => { listeners[name] = callback; } },
  performance: { now: () => 0 },
  requestAnimationFrame: (callback) => { frameQueue.push(callback); },
};
